#!/usr/bin/env bash
set -euo pipefail
[[ ${PHONE_USE_CONFIRMED:-} == yes ]]||{ echo set_PHONE_USE_CONFIRMED >&2;exit 2; }
MODE=${PROVIDER_MODE:-cpu};PHYSICAL_PROOF=${PHYSICAL_PROOF:-no};[[ $MODE == cpu || $MODE == qnn ]]||exit 2;[[ $PHYSICAL_PROOF == yes || $PHYSICAL_PROOF == no ]]||exit 2;[[ $PHYSICAL_PROOF == no || $MODE == qnn ]]||exit 2;[[ ${EXPECTED_EOS+x} && ${EXPECTED_FRAMES+x} ]]||{ echo set_EXPECTED_EOS_and_EXPECTED_FRAMES >&2;exit 2; };TAG=$MODE;[[ $PHYSICAL_PROOF == yes ]]&&TAG=qnn-proof
SERIAL=R5CW81PR8SY;ROOT=$(cd "$(dirname "$0")/../../.."&&pwd);EXP="$ROOT/experiments/0014-pocket-fp-onnx-qnn-htp";STAGE="$EXP/.local/canonical-benchmark-stage";MANIFEST="$EXP/work/canonical-benchmark/stage-sha256.txt";ADB=${ADB:-/mnt/c/Users/mgottschling/AppData/Local/Android/platform-tools-pi/platform-tools/adb.exe};ID="$(date -u +%Y%m%dT%H%M%SZ)-$$";REMOTE="/data/local/tmp/experiment-0014-pocket-canonical-$TAG-$ID";OUT="$EXP/work/canonical-benchmark/phone-$TAG-$ID";mkdir -p "$OUT" "$ROOT/artifacts/locks";exec 9>>"$ROOT/artifacts/locks/phone.lock";flock -n 9||{ echo phone_lock_busy >&2;exit 3;};export ADB_LIBUSB=1
adb(){ "$ADB" -s "$SERIAL" "$@" </dev/null 9>&-; }
cleanup(){ set +e;adb shell "rm -rf '$REMOTE'" >"$OUT/cleanup.stdout" 2>"$OUT/cleanup.stderr";echo $? >"$OUT/cleanup.exit"; }
trap cleanup EXIT
L=$("$ADB" devices -l 9>&-|tr -d '\r');printf '%s\n' "$L">"$OUT/devices.txt";mapfile -t D < <(printf '%s\n' "$L"|awk 'NR>1&&$2=="device"{print $1}');[[ ${#D[@]} == 1 && ${D[0]} == "$SERIAL" ]]||exit 4
{ echo serial=$(adb get-serialno|tr -d '\r');echo model=$(adb shell getprop ro.product.model|tr -d '\r');echo soc=$(adb shell getprop ro.soc.model|tr -d '\r');echo abi=$(adb shell getprop ro.product.cpu.abi|tr -d '\r');echo boot=$(adb shell getprop sys.boot_completed|tr -d '\r');}>"$OUT/identity.txt";grep -Fxq serial=$SERIAL "$OUT/identity.txt";grep -Fxq model=SM-S918B "$OUT/identity.txt";grep -Fxq soc=SM8550 "$OUT/identity.txt";grep -Fxq abi=arm64-v8a "$OUT/identity.txt";grep -Fxq boot=1 "$OUT/identity.txt";adb shell dumpsys thermalservice >"$OUT/thermal-before.txt"||true;adb shell "dumpsys battery | head -n 25" >"$OUT/battery-before.txt"||true
cp "$MANIFEST" "$OUT/local-stage-sha256.txt";adb shell "mkdir -p '$REMOTE/outputs' '$REMOTE/profiles'";adb push "$STAGE/." "$REMOTE/" >"$OUT/push.stdout" 2>"$OUT/push.stderr";adb shell "chmod 755 '$REMOTE/pocket_alba_static_benchmark_runner';cd '$REMOTE';find . -type f -exec sha256sum {} +|sort"|tr -d '\r'>"$OUT/remote-stage-sha256.txt";diff -u "$OUT/local-stage-sha256.txt" "$OUT/remote-stage-sha256.txt"
BACKEND=cpu;PROFILE=-;WARM_RUNS=5;[[ $MODE == qnn ]]&&BACKEND="$REMOTE/lib/libQnnHtp.so";[[ $PHYSICAL_PROOF == yes ]]&&{ PROFILE="$REMOTE/profiles";WARM_RUNS=0; };ENV="export LD_LIBRARY_PATH='$REMOTE/lib' ADSP_LIBRARY_PATH='$REMOTE/lib;/vendor/lib/rfsa/adsp;/vendor/dsp/cdsp;/system/lib/rfsa/adsp;/vendor/dsp'"
set +e
timeout 7200 "$ADB" -s "$SERIAL" shell "cd '$REMOTE' && $ENV && ./pocket_alba_static_benchmark_runner '$REMOTE/model' '$REMOTE/assets/alba-flow-cache-v1.f32' '$REMOTE/assets/canonical-token-ids-64.i64' '$REMOTE/assets/numpy-randomstate-seed0-temp0p3-292x32.f32' '$REMOTE/outputs' '$PROFILE' '$BACKEND' 0.3 292 pocket-fixed-alba-text64-cache512-canonical-v2 '$WARM_RUNS' '$EXPECTED_EOS' '$EXPECTED_FRAMES' >'$REMOTE/result.json' 2>'$REMOTE/result.stderr'" </dev/null 9>&-
run_rc=$?;set -e;printf '%s\n' "$run_rc">"$OUT/runner.exit";adb shell "cd '$REMOTE';find outputs profiles -type f -exec sha256sum {} +|sort;sha256sum result.json result.stderr"|tr -d '\r'>"$OUT/remote-output-sha256.txt"||true;adb pull "$REMOTE/result.json" "$OUT/result.json" >/dev/null 2>&1||true;adb pull "$REMOTE/result.stderr" "$OUT/result.stderr" >/dev/null 2>&1||true;adb pull "$REMOTE/outputs" "$OUT/" >/dev/null 2>&1||true;[[ $PHYSICAL_PROOF == yes ]]&&adb pull "$REMOTE/profiles" "$OUT/" >/dev/null 2>&1||true;adb shell dumpsys thermalservice >"$OUT/thermal-after.txt"||true;adb shell "dumpsys battery | head -n 25" >"$OUT/battery-after.txt"||true
cleanup;trap - EXIT
if adb shell test -e "$REMOTE";then echo cleanup_failed >&2;exit 5;else echo cleanup_ok>"$OUT/cleanup-proof.txt";fi
printf '%s\n' "$OUT";[[ $run_rc == 0 ]]||exit "$run_rc"
